// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A new generation maps the shards it shares with the live generation by retaining the live generation's mapped
 * {@code SharedShard} instead of opening the file again. When the new manifest is rejected, only the new generation's
 * reference may be dropped: the shared mapping still serves the live generation and every query lease on it.
 */
class FrontierSharedShardValidationTest {

	private static final int PROBE_SHARD = 9_000;

	@TempDir
	Path directory;

	private LmdbStatisticsService service;

	@AfterEach
	void closeService() {
		if (service != null) {
			service.close();
		}
	}

	@Test
	void rejectedGenerationNeverClosesAShardTheLiveGenerationStillMaps() throws Exception {
		service = openService();
		FrontierStatisticsManifest one = writeGeneration(1L, -1L, 7L, 41L);
		service.publish(one);
		FrontierStatisticsLease liveLease = service.acquire(7L);
		assertTrue(liveLease.ready());

		// Reuses every shard of generation 1, but claims a base epoch the reused shards were not built from.
		FrontierStatisticsManifest inconsistent = reusingManifest(one, 2L, 8L, 8L);
		FrontierStatisticsException rejected = assertThrows(FrontierStatisticsException.class,
				() -> service.publish(inconsistent));
		assertEquals(FrontierFallbackReason.SHARD_CORRUPT, rejected.fallbackReason(), rejected::toString);

		assertEquals(1L, service.status().generationId(), "a rejected manifest must leave the live generation");
		assertEquals(41L, assertDoesNotThrow(() -> liveLease.shard(PROBE_SHARD).column(0).value(0L),
				"the rejected generation closed a shard mapping that the live generation's lease still reads"));
		liveLease.close();
		try (FrontierStatisticsLease fresh = service.acquire(7L)) {
			assertTrue(fresh.ready());
			assertEquals(41L, assertDoesNotThrow(() -> fresh.shard(PROBE_SHARD).column(0).value(0L),
					"the live generation lost a shared shard mapping to a rejected publication"));
		}

		// The shared mapping must still be reusable by a consistent successor.
		FrontierStatisticsManifest consistent = reusingManifest(one, 2L, 7L, 7L);
		service.publish(consistent);
		assertEquals(2L, service.status().generationId());
		try (FrontierStatisticsLease successor = service.acquire(7L)) {
			assertEquals(41L, successor.shard(PROBE_SHARD).column(0).value(0L));
		}
	}

	@Test
	void rejectedGenerationStillReleasesTheShardItOpenedItself() throws Exception {
		service = openService();
		FrontierStatisticsManifest one = writeGeneration(1L, -1L, 7L, 41L);
		service.publish(one);

		// A fresh (not shared) shard whose header disagrees with the manifest is closed by the failed open.
		FrontierStatisticsManifest two = writeGeneration(2L, 1L, 8L, 82L);
		FrontierStatisticsManifest wrongEpoch = new FrontierStatisticsManifest(two.generationId(),
				two.previousGenerationId(), 9L, 9L, two.coveredSequence(), two.createdAtMillis(),
				two.maximumTermId(), probeShardFirst(two.shards()));
		assertThrows(FrontierStatisticsException.class, () -> service.publish(wrongEpoch));
		assertEquals(1L, service.status().generationId());

		service.publish(two);
		assertEquals(2L, service.status().generationId());
		try (FrontierStatisticsLease current = service.acquire(8L)) {
			assertEquals(82L, current.shard(PROBE_SHARD).column(0).value(0L));
		}
	}

	private static FrontierStatisticsManifest reusingManifest(FrontierStatisticsManifest base, long generationId,
			long baseEpoch, long coveredEpoch) {
		ArrayList<FrontierStatisticsShardDescriptor> reused = new ArrayList<>();
		for (FrontierStatisticsShardDescriptor descriptor : probeShardFirst(base.shards())) {
			reused.add(descriptor.ownedBy(descriptor.resolvedOwnerGenerationId(base.generationId())));
		}
		return new FrontierStatisticsManifest(generationId, base.generationId(), baseEpoch, coveredEpoch,
				base.coveredSequence(), base.createdAtMillis(), base.maximumTermId(), reused);
	}

	/** Validates the probe shard first, so a rejection affects exactly the shard the test reads. */
	private static List<FrontierStatisticsShardDescriptor> probeShardFirst(
			List<FrontierStatisticsShardDescriptor> shards) {
		ArrayList<FrontierStatisticsShardDescriptor> ordered = new ArrayList<>();
		shards.stream().filter(descriptor -> descriptor.shardId() == PROBE_SHARD).forEach(ordered::add);
		shards.stream().filter(descriptor -> descriptor.shardId() != PROBE_SHARD).forEach(ordered::add);
		return ordered;
	}

	private LmdbStatisticsService openService() throws IOException {
		return LmdbStatisticsService.open(directory,
				new FrontierStatisticsHeapGovernor(
						2L * 1024L * 1024L * 1024L,
						256L * 1024L * 1024L,
						512L * 1024L * 1024L,
						256L * 1024L * 1024L),
				128L * 1024L * 1024L * 1024L,
				60_000L,
				Runnable::run);
	}

	private FrontierStatisticsManifest writeGeneration(long generationId, long previousGenerationId, long epoch,
			long value) throws IOException {
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		FrontierStatisticsManifest core = FrontierStatisticsBuilder.build(
				directory, generationId, previousGenerationId, emptySnapshot(epoch), governor, config);
		String fileName = "generation-%019d-shard-%05d.fs2s".formatted(generationId, PROBE_SHARD);
		Path shardPath = directory.resolve(fileName);
		try (FrontierStatisticsShardWriter writer = new FrontierStatisticsShardWriter(
				shardPath, generationId, PROBE_SHARD, epoch, core.maximumTermId(), 1L)) {
			writer.addUnsignedColumn(0, new long[] { value });
			writer.finish();
		}
		FrontierStatisticsShardDescriptor descriptor = new FrontierStatisticsShardDescriptor(
				PROBE_SHARD, FrontierStatisticsTier.EXACT_AND_LINEAR, true, fileName, Files.size(shardPath), 1L);
		ArrayList<FrontierStatisticsShardDescriptor> descriptors = new ArrayList<>(core.shards());
		descriptors.add(descriptor);
		return new FrontierStatisticsManifest(
				core.generationId(), core.previousGenerationId(), core.baseEpoch(), core.coveredEpoch(),
				core.coveredSequence(), core.createdAtMillis(), core.maximumTermId(), descriptors);
	}

	private static FrontierSnapshotSource emptySnapshot(long epoch) {
		return new FrontierSnapshotSource() {
			@Override
			public long snapshotEpoch() {
				return epoch;
			}

			@Override
			public long rowCount(boolean explicit) {
				return 0L;
			}

			@Override
			public long scan(boolean explicit, RawQuadSink sink) {
				return 0L;
			}

			@Override
			public boolean contains(long subjectId, long predicateId, long objectId, long contextId,
					boolean explicit) {
				return false;
			}

			@Override
			public void close() {
			}
		};
	}
}
